function extract(obj){
  if(obj==null) return null;
  const cands=[obj, obj.choices&&obj.choices[0]&&obj.choices[0].message&&obj.choices[0].message.content, obj.message&&obj.message.content, obj.content, obj.text];
  for(let c of cands){
    if(c==null) continue;
    if(typeof c==='string'){ try{ c=JSON.parse(c.replace(/```json|```/g,'').trim()); }catch(e){ continue; } }
    if(c&&typeof c==='object'&&('conteudo' in c||'titulo' in c)) return c;
  }
  return null;
}
const art=extract($input.first().json);
if(!art||!art.titulo){ throw new Error('Nao consegui parsear o artigo retornado pela IA'); }
const tags=Array.isArray(art.tags)?art.tags.join(', '):(art.tags||'');
return [{ json: { id: $('Buscar da Fila').item.json.id, artigo: { titulo: art.titulo||'', conteudo: art.conteudo||'', resumo: (art.resumo||'').slice(0,160), categoria: art.categoria||'Tecnologia', tags } } }];
